from pathlib import Path
import re,sys
app=Path(sys.argv[1]); css=Path(sys.argv[2])
s=app.read_text(encoding='utf-8')
if "APP_VERSION='3.2.1'" in s:
    raise SystemExit(0)

s="import {NotificationQueue,type NotificationType} from './engine/notification-queue.js';\nimport {freshTestSandbox,sanitiseTestState,unlockEverything as unlockTestEverything} from './engine/test-sandbox.js';\n"+s
s=s.replace("APP_VERSION='3.2.0'","APP_VERSION='3.2.1'",1)
s=s.replace("schemaVersion:'3.2.0'","schemaVersion:'3.2.1'").replace("schemaVersion='3.2.0'","schemaVersion='3.2.1'")
s=s.replace("testMode:{enabled:boolean,coins:number,unlockedCosmetics:string[],previewShield:string|null,font:string,overlay:string|null,animation:string|null}","testMode:any")
s=s.replace("testMode:{enabled:false,coins:0,unlockedCosmetics:[],previewShield:null,font:'system',overlay:null,animation:null}","testMode:freshTestSandbox(false)")
s=s.replace("merged.testMode={enabled:false,coins:0,unlockedCosmetics:[],previewShield:null,font:'system',overlay:null,animation:null,...(s?.testMode||{})}","merged.testMode={...freshTestSandbox(false),...(s?.testMode||{})}")

s=s.replace("toastMessage='', toastKind='success',", "toastMessage='', toastKind='success', notificationTimer:ReturnType<typeof setTimeout>|null=null,")
old="function toast(message:string,kind='success'){toastMessage=message;toastKind=kind;render();setTimeout(()=>{if(toastMessage===message){toastMessage='';render()}},2200)}"
new="""const notifications=new NotificationQueue();
function scheduleNotification(){if(notificationTimer)clearTimeout(notificationTimer);const current=notifications.current();if(current&&current.dismissAfterMs>0)notificationTimer=setTimeout(()=>notifications.dismiss(current.notificationId),current.dismissAfterMs)}
notifications.subscribe(()=>{scheduleNotification();if(typeof state!=='undefined'&&state)render()});
function notify(title:string,message:string,type:NotificationType='success',dismissAfterMs=3500,actionLabel?:string){notifications.enqueue({type,title,message,dismissAfterMs,dismissible:true,actionLabel})}
function toast(message:string,kind='success'){const type:NotificationType=kind==='achievement'?'achievement':kind==='error'?'error':'success';notify(type==='achievement'?'Achievement unlocked':type==='error'?'Action needed':'Done',message,type,type==='error'?8000:3500)}"""
if old not in s: raise SystemExit('toast function not found')
s=s.replace(old,new,1)
s=s.replace("toastMessage=`Achievement unlocked: ${a.name} (+${a.coins} coins)`;toastKind='achievement'","toast(`Achievement unlocked: ${a.name} (+${a.coins} coins)`,'achievement')")

s=re.sub(r"function toastView\(\)\{.*?\}\n\nfunction onboarding",'''function toastView(){const n=notifications.current();if(!n)return '';return `<div class="appNotificationHost" aria-live="polite"><section class="appNotification ${esc(n.type)}" role="status" data-notification-id="${esc(n.notificationId)}"><div><b>${esc(n.title)}</b><p>${esc(n.message)}</p></div><button data-action="dismiss-notification" aria-label="Close notification">×</button></section></div>`}

function onboarding''',s,flags=re.S)

about="""function aboutView(){const remaining=Math.max(0,5-versionTapCount);return shell(`<main class="shell"><h1>About</h1><section class="card"><h2>Security+ Adaptive Learning</h2><dl class="aboutGrid"><dt>Application version</dt><dd><button class="versionTap" data-action="version-tap">Version ${APP_VERSION}</button></dd><dt>Content version</dt><dd>${esc(contentPack.contentVersion)}</dd><dt>Curriculum version</dt><dd>1.2</dd><dt>Storage mode</dt><dd>Local browser storage</dd><dt>Offline status</dt><dd>${navigator.onLine?'Online · offline files available':'Offline'}</dd></dl><p class="notice">Tap the version five times to enable local testing tools.</p>${!developerCodeVisible?`<p class="tapProgress">${remaining===5?'Five taps required':`${remaining} tap${remaining===1?'':'s'} remaining`}</p>`:`<p class="tapProgress"><b>Testing tools unlocked</b></p><label>Developer code <input id="test-code" autocomplete="off" spellcheck="false"></label><button class="primary" data-action="test-enable">Enable Test Mode</button><p class="muted">Test Mode is local QA tooling. It does not affect genuine learning progress, readiness or rewards.</p>`}<div class="buttonStack"><button data-action="check-updates">Check for updates</button><button data-action="refresh-files">Refresh application files</button></div><p>${updateAvailable?'Update available.':'The application files are up to date.'}</p>${state.testMode.enabled?`<p class="testWarning"><b>TEST MODE</b> Test actions do not affect genuine mastery, readiness or rewards.</p><button data-nav="testlab">Open Developer Lab</button><button data-action="test-exit">Exit Test Mode</button>`:''}</section></main>`)}"""
s=re.sub(r"function aboutView\(\)\{.*?\}\nfunction cosmeticsView",about+"\nfunction cosmeticsView",s,flags=re.S)

more="""function moreView(){return shell(`<main class="shell"><h1>More</h1><p>Profile, study records and application controls.</p><section class="grid">${[['settings','⚙','Profile and settings','Name, exam date, backup and reset'],['memory','✎','Memory bank','Notes and saved explanations'],['achievements','★','Achievements','Progress and unlocks'],['cosmetics','◆','Cosmetics','Themes, shields and styles'],['reports','⚑','Question reports','Review and export saved reports'],['backup','⇩','Backup and restore',state.lastBackupAt?`Last backup ${new Date(state.lastBackupAt).toLocaleDateString()}`:'No backup recorded'],['about','ⓘ','About and version',`Version ${APP_VERSION}`],...(state.testMode.enabled?[['testlab','🧪','Developer Lab','Local test sandbox']]:[])].map(x=>`<button class="tile" data-nav="${x[0]}"><b>${x[1]} ${x[2]}</b><span>${x[3]}</span></button>`).join('')}</section></main>`)}"""
s=re.sub(r"function moreView\(\)\{.*?\}\nfunction backupView",more+"\nfunction backupView",s,flags=re.S)

lab="""function visualTestLab(){if(!state.testMode.enabled)return aboutView();const shields=['shield-basic','shield-bronze','shield-silver','shield-gold','shield-platinum','shield-diamond','shield-master'];const cosmetics=cosmeticCatalogue.map(x=>String(x[0]));return shell(`<main class="shell testLab"><p class="eyebrow">TEST PREVIEW</p><h1>Developer Lab</h1><p class="testWarning"><b>TEST MODE</b> Test actions do not affect genuine mastery, readiness or rewards.</p><section class="card"><h2>Test profile</h2><button class="primary wide" data-action="test-unlock-everything">UNLOCK EVERYTHING FOR TESTING</button><p><b>Real coins:</b> ${state.coins} · <b>Test coins:</b> ${state.testMode.unlimitedCoins?'Unlimited':state.testMode.coins}</p><button data-action="test-lock-all">Lock all test items</button><button data-action="test-unlimited">Set test coins to unlimited</button><button data-test-grant="100">Grant 100 test coins</button><button data-test-grant="10000">Grant 10,000 test coins</button><button data-action="test-reset">Reset test-only data</button></section><section class="card"><h2>Shields</h2>${shieldMarkup('large')}<div class="previewGrid">${shields.map(x=>`<button data-test-shield="${x}">Preview ${x.replace('shield-','')}</button>`).join('')}</div><button data-test-animation="rank-up">Preview shield rank-up</button></section><section class="card"><h2>Achievements</h2>${[['locked','Locked achievement'],['partial','Partial progress'],['almost','Almost complete'],['unlocked','Achievement unlocked'],['queued','Multiple queued achievements'],['complete','Completed gallery']].map(x=>`<button data-achievement-state="${x[0]}">${x[1]}</button>`).join('')}</section><section class="card"><h2>Feedback</h2>${[['feedback-correct','Correct answer'],['feedback-low','Correct but low confidence'],['feedback-wrong','Incorrect answer'],['dontknow','I don’t know'],['teach','Teach me'],['forgot','I forgot'],['confusing','Confusion comparison'],['retest','Answer retest']].map(x=>`<button data-test-overlay="${x[0]}">Preview ${x[1]}</button>`).join('')}</section><section class="card"><h2>Notifications</h2><button data-notification-preview="success">Success</button><button data-notification-preview="achievement">Achievement</button><button data-notification-preview="coins">Coins</button><button data-notification-preview="shield">Shield</button><button data-notification-preview="error">Error</button><button data-action="test-notification-queue">Multiple queued notifications</button></section><section class="card"><h2>Bosses</h2><button data-test-boss="boss">Any Unit Boss</button><button data-test-boss="boss-objective">Any Objective Boss</button><button data-test-boss="boss-domain">Any Domain Boss</button><button data-test-boss="boss-final">Final Readiness Boss</button>${['all-correct','threshold','below-threshold','perfect','entrance','hit','critical','defeated','survived','claimed','repeat'].map(x=>`<button data-boss-scenario="${x}">${x.replaceAll('-',' ')}</button>`).join('')}</section><section class="card"><h2>Question and lesson states</h2><button data-test-screen="session">Start reviewed question</button><button data-test-overlay="concept-card">Concept card</button><button data-test-overlay="lesson-empty">No-question lesson</button><button data-test-overlay="report">Question report flow</button><button data-test-overlay="exam-empty">Exam Mode empty state</button></section><section class="card"><h2>Application states</h2>${['home','learn','review','dashboard','more','settings','backup','memory','achievements','cosmetics','reports','about'].map(x=>`<button data-test-screen="${x}">Open ${x}</button>`).join('')}<button data-test-overlay="offline">Offline state</button><button data-test-overlay="update">Update available</button><button data-test-overlay="updated">Update installed</button><button data-test-overlay="import-success">Import success</button><button data-test-overlay="import-failure">Import failure</button><button data-test-overlay="backup-reminder">Backup reminder</button><button data-test-overlay="empty">Empty state</button></section><section class="card"><button class="primary wide" data-action="test-exit">Exit Test Mode</button></section></main>`)}"""
s=re.sub(r"function visualTestLab\(\).*?\n\nfunction testOverlay",lab+"\n\nfunction testOverlay",s,flags=re.S)

# Render every restored route.
render="""function render(){app.innerHTML=(view==='onboarding'?onboarding():view==='home'?home():view==='learn'?learn():view==='lesson'?lesson():view==='session'?session():view==='feedback'?feedbackView():view==='dashboard'?dashboard():view==='acronyms'?acronymsView():view==='exam'?examView():view==='memory'?memoryView():view==='review'?reviewView():view==='achievements'?achievementsView():view==='reports'?reportsView():view==='more'?moreView():view==='backup'?backupView():view==='about'?aboutView():view==='testlab'?visualTestLab():view==='cosmetics'?cosmeticsView():view==='boss-result'?bossResultView():settingsView())+aiPanel()+reportPanel()+testOverlay()+toastView();document.documentElement.dataset.theme=state?.testMode?.enabled&&state.testMode.equippedTheme?state.testMode.equippedTheme:state?.cosmetics?.equippedTheme||'theme-blue';document.documentElement.dataset.font=state?.testMode?.enabled?state.testMode.font:'system';if(view==='session'||view==='feedback')document.querySelector('nav')?.remove()}"""
s=re.sub(r"function render\(\)\{.*?\}\napp\.addEventListener",render+"\napp.addEventListener",s,flags=re.S)

# Remove every old version-tap branch, then add one reliable branch.
s=re.sub(r"if\(a==='version-tap'\)\{.*?return\}","",s)
anchor="if(a==='test-enable')"
branch="if(a==='dismiss-notification'){notifications.dismiss(t.closest<HTMLElement>('[data-notification-id]')?.dataset.notificationId);return}if(a==='version-tap'){versionTapCount=Math.min(5,versionTapCount+1);if(versionTapCount===5){developerCodeVisible=true;notify('Testing tools unlocked','Enter the local QA code to enable Test Mode.','info',4000)}render();return}if(a==='check-updates'){navigator.serviceWorker?.getRegistration().then(r=>r?.update());notify('Update check started','The app is checking for newer files.','info',3500);return}if(a==='refresh-files'){caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('security-plus-')).map(k=>caches.delete(k)))).then(()=>location.reload());return}"
s=s.replace(anchor,branch+anchor,1)

s=s.replace("state.testMode.enabled=true;save();view='testlab';toast('TEST MODE enabled')","state.testMode={...freshTestSandbox(true),...state.testMode,enabled:true};save();view='testlab';toast('TEST MODE enabled')")
s=s.replace("state.testMode.enabled=false;developerCodeVisible=false;versionTapCount=0;save();view='settings';toast('TEST MODE disabled')","state.testMode.enabled=false;developerCodeVisible=false;versionTapCount=0;save();view='about';toast('TEST MODE disabled')")
s=s.replace("state.testMode={enabled:true,coins:0,unlockedCosmetics:[],previewShield:null,font:'system',overlay:null,animation:null};save();toast('Test-only data reset')","state.testMode=freshTestSandbox(true);save();toast('Test-only data reset')")

insert="""if(a==='test-unlock-everything'&&state.testMode.enabled){state.testMode=unlockTestEverything(state.testMode,cosmeticCatalogue.map(x=>String(x[0])));save();toast('Everything unlocked for testing');return}if(a==='test-lock-all'&&state.testMode.enabled){state.testMode={...freshTestSandbox(true)};save();toast('All test items locked');return}if(a==='test-unlimited'&&state.testMode.enabled){state.testMode.unlimitedCoins=true;state.testMode.coins=Number.MAX_SAFE_INTEGER;save();toast('Test coins set to unlimited');return}if(t.dataset.achievementState&&state.testMode.enabled){state.testMode.achievementState=t.dataset.achievementState;state.testMode.overlay='achievement';save();render();return}if(t.dataset.notificationPreview&&state.testMode.enabled){const kind=t.dataset.notificationPreview as NotificationType;notify(`Test ${kind}`,`This is a ${kind} notification preview.`,kind,kind==='error'?8000:3500);return}if(a==='test-notification-queue'&&state.testMode.enabled){notify('First achievement','Queued preview one.','achievement');notify('Second achievement','Queued preview two.','achievement');notify('Coin reward','Queued preview three.','coins');return}if(t.dataset.bossScenario&&state.testMode.enabled){state.testMode.bossScenario=t.dataset.bossScenario;state.testMode.overlay='boss-'+t.dataset.bossScenario;save();render();return}if(t.dataset.testScreen&&state.testMode.enabled){if(t.dataset.testScreen==='session'){try{start(2,'adaptive',true)}catch(err){toast(String(err),'error')}}else navigate(t.dataset.testScreen);return}"""
s=s.replace("if(t.dataset.testGrant&&state.testMode.enabled)",insert+"if(t.dataset.testGrant&&state.testMode.enabled)",1)

# Test cosmetics never touch genuine coins, ownership or equipped state.
pattern=r"if\(t\.dataset\.cosmetic\)\{.*?return\}const a=t\.dataset\.action;"
replacement="""if(t.dataset.cosmetic){const item=t.dataset.cosmetic!,cost=Number(t.dataset.cost||0);if(state.testMode.enabled){if(!state.testMode.unlockEverything&&!state.testMode.unlockedCosmetics.includes(item)){if(!state.testMode.unlimitedCoins&&state.testMode.coins<cost){toast('Not enough test coins','error');return}if(!state.testMode.unlimitedCoins)state.testMode.coins-=cost;state.testMode.unlockedCosmetics.push(item)}if(item.startsWith('theme-'))state.testMode.equippedTheme=item;else state.testMode.equippedShield=item;save();toast('Test cosmetic equipped');return}const owned=state.cosmetics.owned.includes(item);if(!owned){if(state.coins<cost){toast('Not enough coins','error');return}state.coins-=cost;state.cosmetics.owned.push(item);state.events.push(emit('cosmetic_unlocked',[],{item,cost}))}if(item.startsWith('theme-'))state.cosmetics.equippedTheme=item;else state.cosmetics.equippedShield=item;state.events.push(emit('cosmetic_equipped',[],{item}));save();toast('Cosmetic equipped');return}const a=t.dataset.action;"""
s=re.sub(pattern,replacement,s,flags=re.S)

# Exclude all test-only state from genuine backup.
s=re.sub(r"const exportState=\{\.\.\.state,testMode:\{.*?\}\};", "const exportState=sanitiseTestState(state);", s, flags=re.S)

# Update controller-change notification.
s=s.replace("toastMessage='Updated successfully';toastKind='success';render()","notify('Update completed',`Updated to v${APP_VERSION}`,'update',4000)")

app.write_text(s,encoding='utf-8')

c=css.read_text(encoding='utf-8')
c=re.sub(r"\.toast\{.*?\}","",c,flags=re.S)
c+='''
.appNotificationHost{position:fixed;left:12px;right:12px;bottom:calc(env(safe-area-inset-bottom,0px) + 88px);z-index:80;pointer-events:none;display:flex;justify-content:center}.appNotification{width:min(680px,100%);box-sizing:border-box;background:#142033;border:1px solid #58708f;border-radius:16px;padding:14px 14px 14px 16px;display:flex;gap:12px;align-items:flex-start;justify-content:space-between;box-shadow:0 12px 32px rgba(0,0,0,.42);pointer-events:auto}.appNotification p{margin:.25rem 0 0}.appNotification button{min-width:44px;min-height:44px;border:0;background:transparent;font-size:1.5rem}.appNotification.error{border-left:5px solid #ff8b8b}.appNotification.achievement,.appNotification.coins,.appNotification.shield{border-left:5px solid #f3c969}.appNotification.success,.appNotification.update{border-left:5px solid #6ee7b7}.questionScreen,.feedbackScreen{padding-bottom:220px}.aboutGrid{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px 16px}.aboutGrid dt{color:#a9b7ca}.aboutGrid dd{margin:0;text-align:right}.tapProgress{font-weight:700}.buttonStack{display:grid;gap:10px}.testLab .card button{margin:5px;min-height:48px}.testWarning{border-left:5px solid #f3a600;background:#332711;padding:12px}.testModeBadge{white-space:nowrap}
@media(max-width:420px){.appNotificationHost{left:8px;right:8px;bottom:calc(env(safe-area-inset-bottom,0px) + 82px)}.questionScreen,.feedbackScreen{padding-bottom:230px}.aboutGrid{grid-template-columns:1fr}.aboutGrid dd{text-align:left}}
@media(prefers-reduced-motion:reduce){.appNotification,.testOverlay,.bossVisual{animation:none!important;transition:none!important}}
'''
css.write_text(c,encoding='utf-8')
